import{d as g,C as n,o as d,c as p,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"震为雷","description":"震为雷，震上震下","frontmatter":{"title":"震为雷","description":"震为雷，震上震下","category":"hexagram","aliases":["震","震为雷"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-51.md","filePath":"yijing/hexagrams/hexagram-51.md","lastUpdated":1787800334000}'),h={name:"yijing/hexagrams/hexagram-51.md"},x=g({...h,setup(m){const r=[{id:"zhen",term:"震",pinyin:"zhèn",meaning:"雷；震动、惊惧。震卦的「震」既是雷，也是震动的处境与内心的惊惧。"},{id:"xixi",term:"虩虩",pinyin:"xì xì",meaning:"恐惧惊顾、惶恐不安的样子。"},{id:"yaya",term:"哑哑",pinyin:"yā yā",meaning:"笑声、谈笑声。惊惧过去之后恢复从容的声音。"},{id:"bichang",term:"匕鬯",pinyin:"bǐ chàng",meaning:"匕是祭祀用的勺匙，鬯是祭祀用的香酒；合指祭祀的核心器物与仪式，引申为最核心、最不可失的东西。",context:"震惊百里，不丧匕鬯——震得再响，手里的核心不丢。"},{id:"yi",term:"亿",pinyin:"yì",meaning:"通「臆」，揣度、估量。「亿丧贝」即估量之下会失去财货。"},{id:"bei",term:"贝",pinyin:"bèi",meaning:"贝壳，古时货币；泛指财货、身外之物。"},{id:"jiuling",term:"九陵",pinyin:"jiǔ líng",meaning:"重重高陵，指远离危地的高处。"},{id:"wuzhu",term:"勿逐",pinyin:"wù zhú",meaning:"不要去追逐、追讨。"},{id:"qiride",term:"七日得",pinyin:"qī rì dé",meaning:"七日之后失而复得。"},{id:"susu",term:"苏苏",pinyin:"sū sū",meaning:"战战兢兢、恐惧不安的样子。"},{id:"sheng",term:"眚"},{id:"suini",term:"遂泥",pinyin:"suì ní",meaning:"陷入泥中。「遂」通「坠」。陷在泥里，动弹不得。"},{id:"wanglaili",term:"往来厉",pinyin:"wǎng lái lì",meaning:"往来皆危，进退都是危险。"},{id:"youshi",term:"有事",pinyin:"yǒu shì",meaning:"有要承担的事、有职责在身。",context:"守得住事，才守得住核心。"},{id:"suosuo",term:"索索",pinyin:"suǒ suǒ",meaning:"恐惧退缩、战栗发抖的样子。"},{id:"juejue",term:"矍矍",pinyin:"jué jué",meaning:"惊惶四顾、目光游移不定。"},{id:"zheng",term:"征",pinyin:"zhēng",meaning:"前往、进取、出征。"},{id:"jian",term:"洊",pinyin:"jiàn",meaning:"通「荐」，再次、接连。「洊雷」即雷声接连而至。"}],e=[{position:"初九",type:"yang",text:"震来虩虩，后笑言哑哑，吉。",xiang:"震来虩虩，恐致福也。笑言哑哑，后有则也。",textModern:"震动袭来，一开始惊惧得左顾右盼；过后能恢复从容、谈笑自若，吉祥。",xiangModern:"震动袭来而恐惧，是敬畏之心带来福分；过后能笑言自若，是因为经历之后有了法则分寸。"},{position:"六二",type:"yin",text:"震来厉，亿丧贝，跻于九陵，勿逐，七日得。",xiang:"震来厉，乘刚也。",textModern:"震动来得猛烈危险，估量之下会丢失财货；登上高陵避险，不去追逐失去的东西，七日之后失而复得。",xiangModern:"震动来得猛烈危险，是因为六二阴爻凌乘于初九阳爻之上，正处险地。"},{position:"六三",type:"yin",text:"震苏苏，震行无眚。",xiang:"震苏苏，位不当也。",textModern:"震动使人战战兢兢；但在这惊恐中前行，不会有灾祸。",xiangModern:"震得战战兢兢，是因为六三阴爻居阳位、位不当；但只要动起来前行，仍可无灾。"},{position:"九四",type:"yang",text:"震遂泥。",xiang:"震遂泥，未光也。",textModern:"震动了，却陷入泥中，动弹不得。",xiangModern:"陷在泥中不能自拔，是因为阳气未能光大、被困于阴柔之中。"},{position:"六五",type:"yin",text:"震往来厉，亿无丧，有事。",xiang:"震往来厉，危行也。其事在中，大无丧也。",textModern:"震动往来、进退皆危；但估量之下无所丧失，因为还有该承担的事——守住核心职责。",xiangModern:"往来皆危，是危险中前行；但因居守中道、有事可守，所以大无丧失。"},{position:"上六",type:"yin",text:"震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。",xiang:"震索索，中未得也。虽凶无咎，畏邻戒也。",textModern:"震动使人恐惧瑟缩、目光惊惶，此时冒进则凶；震动没有落到自己身上、只震到邻人，借邻之戒反躬自省，可以无咎；但过分戒备，连婚事也会招来闲话。",xiangModern:"恐惧瑟缩，是因为上六不居中位、心中无主；虽有凶险却可无咎，是因为能以邻人之灾为戒。"}];return(u,t)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),p("div",null,[i(o,{name:"震",fullName:"震为雷",upper:"☳",lower:"☳",guaCi:"震，亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。",pinyin:["zhèn"],element:"木",direction:"东",virtue:"动",insight:"雷上雷下，震动相接；惊远惧迩，恐惧修省，震中守住核心。",guaSlug:"51zhenweilei",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>洊雷，震。君子以恐惧修省。</p><p>雷声接连而至、一声催着一声，正是震动之象；君子由此悟到，要在震动中保持警惧，回身检视自己。</p><p>「恐惧修省」四字——<strong>恐惧</strong>是对危险的敬畏，是警报在响；<strong>修省</strong>是回到自身，检视、修正。恐惧修省，就是把外界的雷声，转化为内心的检查。</p><p>分形结构：</p><ul><li>恐惧（应激）→ 微观：警觉当下，不被麻痹</li><li>修省（反身）→ 宏观：建立体系，守稳核心</li></ul><p>恐惧是提醒，修省是动作。只恐惧不修省，是白白受惊；只修省不恐惧，是自欺欺人。雷不会白响，响一声，就要修一分。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>震亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。</p><p>逐句释义：</p><ul><li><strong>震亨</strong> —— 震动是亨通的。震带来惊惧，也带来惊醒与新生；动则通，通则久。</li><li><strong>震来虩虩，恐致福也</strong> —— 震动袭来而惊惧四顾，这敬畏之心反而招来福分。恐惧是警报，不是敌人。</li><li><strong>笑言哑哑，后有则也</strong> —— 惊惧之后能恢复笑谈，是因为经历之后建立了法则与分寸。</li><li><strong>震惊百里，惊远而惧迩也</strong> —— 震动的威力惊动远处、警惧近处，远近都被震动而不敢懈怠。</li><li><strong>出可以守宗庙社稷，以为祭主也</strong> —— 经得起震动的人，出则可以守住宗庙社稷、做祭祀的主持者。惊而不乱、守得住核心，才配托付最重的事。</li></ul><blockquote><p><strong>震动哲学</strong>：雷不是来吓你的，是来叫醒你的。被动挨震，是损耗；主动借震修省，是把危机变成修炼的场。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"木",guaSlug:"51zhenweilei",glossary:r,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-震来虩虩-后笑言哑哑-吉" tabindex="-1">初九 · 震来虩虩，后笑言哑哑，吉 <a class="header-anchor" href="#初九-·-震来虩虩-后笑言哑哑-吉" aria-label="Permalink to &quot;初九 · 震来虩虩，后笑言哑哑，吉&quot;">​</a></h3><ul><li><strong>震来虩虩</strong> → 震动袭来，惊惧四顾</li><li><strong>后笑言哑哑</strong> → 过后从容，谈笑自若</li><li><strong>恐致福也</strong> → 恐惧不是坏事，是敬畏心；敬畏，招福</li><li><strong>后有则也</strong> → 笑言不是因为麻木，是因为经历之后有了法则</li></ul><p>初九刚居阳位，是第一个被震到的人。恐惧是正常的应激反应：先惊、后定。真正重要的是那个「后」字——惊过之后，能不能恢复。</p><p><strong>恐致福</strong>：对危险有敬畏，人就不会麻痹；<strong>后有则</strong>：经历震动之后，人建立了自己的尺度。初九的吉，不在「不惧」，在「惧而后定」。</p><blockquote><p>核心洞见：正常的恐惧不是懦弱，是警报系统在工作。关键不在「怕不怕」，在「怕完之后能不能笑出来」——能笑，说明警报响过、系统正常、分寸已立。</p></blockquote><h3 id="六二-·-震来厉-亿丧贝-跻于九陵-勿逐-七日得" tabindex="-1">六二 · 震来厉，亿丧贝，跻于九陵，勿逐，七日得 <a class="header-anchor" href="#六二-·-震来厉-亿丧贝-跻于九陵-勿逐-七日得" aria-label="Permalink to &quot;六二 · 震来厉，亿丧贝，跻于九陵，勿逐，七日得&quot;">​</a></h3><ul><li><strong>震来厉</strong> → 震动来得猛烈危险</li><li><strong>亿丧贝</strong> → 估量之下，财货要丢</li><li><strong>跻于九陵</strong> → 登上高陵避险</li><li><strong>勿逐</strong> → 不去追逐</li><li><strong>七日得</strong> → 七日之后，失而复得</li></ul><p>六二阴居阴位，又乘刚（凌乘初九阳爻），是恐惧最深、损失最直接的处境。但爻辞给的是极简对策：丢了的，别追。登高避险，先保住人，别贪贝。七日得——失去的东西，不追，反而会回来。</p><p><strong>不追逐的智慧</strong>：损失已经发生，追回去只会二次受伤。恐惧让人本能地想抓，但抓得越紧，丢得越多。先登高（保核心），再勿逐（不恋战），七日得（时间会还给你）。</p><blockquote><p>核心洞见：失去不是最可怕的，追着失去跑才是最可怕的。真正的止损，是停止追损。</p></blockquote><h3 id="六三-·-震苏苏-震行无眚" tabindex="-1">六三 · 震苏苏，震行无眚 <a class="header-anchor" href="#六三-·-震苏苏-震行无眚" aria-label="Permalink to &quot;六三 · 震苏苏，震行无眚&quot;">​</a></h3><ul><li><strong>震苏苏</strong> → 震得战战兢兢、脚步发软</li><li><strong>震行无眚</strong> → 但带着恐惧走，反而没有灾祸</li></ul><p>六三位不当（阴居阳位），是个恐惧发抖的人。爻辞没有让她停，而是说「行」——怕，也要走。无眚的关键不是消除恐惧，而是「行」：在恐惧中行动，才不会有灾。</p><p><strong>带着恐惧行动</strong>：勇气不是不怕，是怕着也走。停在原地被震到麻木，是九四；怕着往前走，是无眚。</p><blockquote><p>核心洞见：恐惧面前只有两种失败——停下来，或逃回去。怕着往前走，恰恰是最安全的一种走法。</p></blockquote><h3 id="九四-·-震遂泥" tabindex="-1">九四 · 震遂泥 <a class="header-anchor" href="#九四-·-震遂泥" aria-label="Permalink to &quot;九四 · 震遂泥&quot;">​</a></h3><ul><li><strong>震遂泥</strong> → 震动袭来，却陷进泥里，动弹不得</li></ul><p>九四是全卦唯一的阳居阴位，刚气被阴柔包围，想动却陷泥。它是恐惧处理的「反面教材」：既没有初九的「后有则」，也没有六三的「行」，而是麻痹——被震到泥里，干脆不动了。</p><p><strong>接受困境</strong>：九四的功课是正视——承认自己陷在泥里，比假装没陷要强得多。「未光也」：阳气发不出来，是因为没有正视、没有启动。麻痹不是平静，是放弃。</p><blockquote><p>核心洞见：最怕的不是泥，是习惯了泥。承认陷落，是出泥的第一步。</p></blockquote><h3 id="六五-·-震往来厉-亿无丧-有事" tabindex="-1">六五 · 震往来厉，亿无丧，有事 <a class="header-anchor" href="#六五-·-震往来厉-亿无丧-有事" aria-label="Permalink to &quot;六五 · 震往来厉，亿无丧，有事&quot;">​</a></h3><ul><li><strong>震往来厉</strong> → 震动往来不停，进退皆危</li><li><strong>亿无丧</strong> → 但估量下来，无所丧失</li><li><strong>有事</strong> → 因为有该承担的事、守得住的职责</li></ul><p>六五居君位（中位），是危机四伏却手握核心的人。往来皆厉，看起来步步惊心；但「有事」——手里有祭祀的职责（匕鬯）、有核心使命。只要守住这个核心，就「大无丧」。这正是卦辞「震惊百里，不丧匕鬯」的爻象版本。</p><p><strong>守住核心</strong>：危机四伏时，目标不是消灭所有风险，而是守住最重要的一件事。核心在，丧的都可以再得；核心失，再安全也无意义。</p><blockquote><p>核心洞见：危机不是用来躲的，是用来守的。六五的底气，不来自没有危险，来自「有事」可守。</p></blockquote><h3 id="上六-·-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言" tabindex="-1">上六 · 震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言 <a class="header-anchor" href="#上六-·-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言" aria-label="Permalink to &quot;上六 · 震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言&quot;">​</a></h3><ul><li><strong>震索索，视矍矍</strong> → 恐惧得瑟缩发抖、目光惊惶四顾</li><li><strong>征凶</strong> → 这种状态下冒进，凶</li><li><strong>震不于其躬，于其邻</strong> → 震动没有落到自己身上，只震到邻居</li><li><strong>无咎</strong> → 以邻为戒、反躬自省，无咎</li><li><strong>婚媾有言</strong> → 但过度戒备，连亲事都会招来闲话</li></ul><p>上六是恐惧的顶点，也是唯一的「过度恐惧」：震动其实已经过去了（震于邻而不于其躬），她却还草木皆兵。爻辞给出两条路：一味害怕、贸然冒进（征凶）；或以邻为戒、回到自身（无咎）。</p><p><strong>警惕过度恐惧</strong>：恐惧的尽头不是安全，是过敏。震动已过，还在怕，是让过去的雷声绑架现在的生活。「畏邻戒也」——把别人的经历当成自己的演练就够了，不必把每个声响都当成雷。</p><blockquote><p>核心洞见：恐惧和草木皆兵之间，只隔一个「过度」。能分得清「震于其躬」还是「震于其邻」，就守住了恐惧的边界。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(s,{title:"字词释义",items:[{term:"震",pinyin:["zhèn"],meaning:"雷；震动、惊惧。震卦的「震」既是雷，也是震动的处境与内心的惊惧。"},{term:"虩虩",pinyin:["xì","xì"],meaning:"恐惧惊顾、惶恐不安的样子。"},{term:"哑哑",pinyin:["yā","yā"],meaning:"笑声、谈笑声。惊惧过去之后恢复从容的声音。"},{term:"匕鬯",pinyin:["bǐ","chàng"],meaning:"匕是祭祀用的勺匙，鬯是祭祀用的香酒；合指祭祀的核心器物与仪式，引申为最核心、最不可失的东西。「震惊百里，不丧匕鬯」即震得再响，手里的核心不丢。"},{term:"亿",pinyin:["yì"],meaning:"通「臆」，揣度、估量。「亿丧贝」即估量之下会失去财货。"},{term:"贝",pinyin:["bèi"],meaning:"贝壳，古时货币；泛指财货、身外之物。"},{term:"九陵",pinyin:["jiǔ","líng"],meaning:"重重高陵，指远离危地的高处。「跻于九陵」即登高避险。"},{term:"勿逐",pinyin:["wù","zhú"],meaning:"不要去追逐、追讨。「勿逐，七日得」——失去的不追，反会回来。"},{term:"苏苏",pinyin:["sū","sū"],meaning:"战战兢兢、恐惧不安的样子。"},{term:"眚"},{term:"遂泥",pinyin:["suì","ní"],meaning:"陷入泥中。「遂」通「坠」。陷在泥里，动弹不得。"},{term:"往来厉",pinyin:["wǎng","lái","lì"],meaning:"往来皆危，进退都是危险。"},{term:"索索",pinyin:["suǒ","suǒ"],meaning:"恐惧退缩、战栗发抖的样子。"},{term:"矍矍",pinyin:["jué","jué"],meaning:"惊惶四顾、目光游移不定。"},{term:"洊",pinyin:["jiàn"],meaning:"通「荐」，再次、接连。「洊雷」即雷声接连而至。"},{term:"恐惧修省",pinyin:["kǒng","jù","xiū","xǐng"],meaning:"有所畏惧而修身反省。恐惧是敬畏，修省是检视修正。"},{term:"婚媾有言",pinyin:["hūn","gòu","yǒu","yán"],meaning:"婚事招来闲话。极度的戒惧，会让最亲近的结合都生出嫌隙。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>震卦讲的是<strong>震动的应对</strong>。上下皆震（☳☳），雷声接连而至、一声催着一声。恐惧临身时人怎么做，决定了震是灾还是福。</p><p>卦辞「震，亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯」点明核心：震动再大，也要守住手里的核心——震惊百里，匕鬯不丧。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>恐惧是双刃剑：太少会麻痹，太多会瘫痪。震卦六爻，正好铺出恐惧应对的完整光谱——初九的正常应激、六二的不追逐、六三的带惧而行、九四的正视困境、六五的守住核心、上六的警惕过度。</p><p>恐惧不是要被消灭的，是要被管理的。能管理恐惧的人，才扛得住百里之惊、托得起宗庙之重。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>震来时先守核心：先稳住「匕鬯」——最重要的一件事，再谈其他</li><li>失去的别追：损失确认就翻篇，勿逐，七日得</li><li>怕着也要走：带着恐惧行动，好过停在原地</li><li>以邻为戒：把别人的教训当演练，但别草木皆兵</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>震卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>震惊百里，不丧匕鬯</td><td>震动再大，守住核心</td><td>守核心</td></tr><tr><td>初九</td><td>震来虩虩，后笑言哑哑，吉</td><td>恐惧是正常应激，怕过之后恢复</td><td>后有则</td></tr><tr><td>六二</td><td>亿丧贝，跻于九陵，勿逐，七日得</td><td>失去不追，先保核心，等它回来</td><td>勿逐七日得</td></tr><tr><td>六三</td><td>震苏苏，震行无眚</td><td>带着恐惧行动，怕着也走</td><td>带惧而行</td></tr><tr><td>九四</td><td>震遂泥</td><td>正视困境，不麻痹</td><td>正视不麻痹</td></tr><tr><td>六五</td><td>震往来厉，亿无丧，有事</td><td>危机四伏，守住核心职责</td><td>有事守中</td></tr><tr><td>上六</td><td>震索索，视矍矍，征凶</td><td>震动已过，别草木皆兵</td><td>畏邻戒也</td></tr></tbody></table><p>震卦的行动哲学，落到三个词：</p><ol><li><strong>风险哲学</strong>——风险是常态，不是意外。震一定会来，能选的不是「震不震」，而是「怎么应对震」</li><li><strong>行动哲学</strong>——恐惧不是停止的理由。怕，也要行；带着恐惧前进，好过停在原地</li><li><strong>心态哲学</strong>——恐惧是警报，不是敌人。管理恐惧，而不是消灭恐惧；守得住核心，就守得住自己</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>震卦是一部「恐惧应对」的成长史。昇哥的人生，恰好把六个爻完整演了一遍：</p><ul><li><strong>初九</strong> → 已经历：转行之初的惊惧四顾，也笑言哑哑过——怕完之后能恢复，说明警报系统正常、分寸已立</li><li><strong>六二</strong> → 大四自学前端：曾经的沉没成本是「丧贝」，登九陵避险、勿逐，一门心思扎进去，七日得——如今安身立命的本事，是时间还回来的</li><li><strong>六三</strong> → 找工作：心里苏苏直抖、怕被拒绝，但带着恐惧一家家投、一次次面，震行无眚——怕着也走，走出来了</li><li><strong>九四</strong> → 已经历：也陷过泥，停过、拖过；正视之后，才重新启动</li><li><strong>六五</strong> → 刚毕业：危机四伏（环境、竞争、未知），但手里有「有事」——有技术、有作品、有方向，守住核心就无丧</li><li><strong>上六</strong> → 乒乓球故事与替代性恐惧：震动其实已过，却把别人的挫折、远方的风声当成自己的雷，草木皆兵；乒乓球教会他的，正是「震不于其躬，于其邻，无咎」——以邻为戒，但别把邻人的球当自己的球</li></ul><p>恐惧递进的六个爻，每一步都真实走过。震卦的答案不在「不震」，而在「震中守得住核心」——震惊百里，匕鬯不丧。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：艮（第五十二卦）、归妹（第五十四卦）</li><li>震与艮的连结：震为动、艮为止，震艮相对、动静互济。震是雷，艮是山——雷动而山止。震教你在震动中行动、守稳核心；艮教你在该止处停止、知止有定。动而不止则疲，止而不动则滞，一动一止才是完整节奏。</li><li>归妹卦的连结：归妹上震下兑，以震为动——结合、合作也要经得起震动的考验。震卦上六「婚媾有言」与归妹的婚配意象呼应：过度戒惧，连最亲近的结合都会生出嫌隙。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',20))])}}});export{c as __pageData,x as default};
